extensions=[
('E01','检索的召回与精度如何权衡','compare', [['高召回策略','扩展术语和数据库，保留低相关候选，增加人工筛选负担。'],['高精度策略','收紧字段和条件，但可能遗漏术语不同的研究。'],['评价','用已知相关文献检查漏检，并记录哪些限制导致排除。']], '让学员在相同候选集上分别给出宽和窄检索式，记录已知相关文献是否被检出。评价必须有参考标准。结果数量越多不等于综述越完整。检索字段、时间范围和语种限制逐项解释。'),
('E02','多篇论文结论冲突的拆解','table', [['差异','检查内容','解释边界'],['样本','对象、纳入和环境','不能直接外推'],['测量','工具、单位和阈值','先统一定义'],['设计','对照、混杂与时间','不能只看p值'],['分析','模型、缺失和多重比较','保留替代解释']], '用企鹅论文的不同物种与年份作为结构例子，不杜撰第二篇论文的结果。讨论如果两项研究方向相反，需要哪些信息才能比较。请学员列出可解释冲突但尚未验证的假说。'),
('E03','缺失机制影响推断的练习','compare', [['完全随机缺失','缺失与观测和未观测值均无关是一种强假设。'],['条件随机缺失','给定观测变量后，缺失不再依赖未观测值。'],['非随机缺失','缺失仍依赖未观测值，需要敏感性分析和领域判断。']], '用体重记录丢失的教学情景区分机制：纸张随机损坏、某岛采集条件差、较重个体更难测量。情景为假设，不声称真实企鹅数据符合其中某一种。删除缺失或多重插补都依赖假设。'),
('E04','训练集与评价集的隔离','route', [['开发材料','调整提示词与参数','保存尝试记录'],['冻结工具与规则','固定检索与纳排','禁止看测试后继续优化'],['独立评价','比较预设指标','报告所有预设结果'],['外部验证','新时间或新机构','检查可迁移性']], '讨论模型选择、提示词选择和数据清洗都可能泄漏评价信息。教学例子不提供虚构准确率。要求学员明确每一次人工看结果是否改变了工具，以及最终评价是否仍独立。'),
('E05','预算约束下的设计取舍','table', [['资源','收缩方式','需要保留'],['经费有限','缩小问题或样本范围','主要比较与质量控制'],['模型不可用','使用固定离线材料','清楚说明回放属性'],['设备排期','预先准备替代测量','测量一致性检查'],['人员不足','减少次要结局','独立复核关口']], '让学员为一个学期内完成的教学研究制定可行路径。减少样本后应重新讨论精度和目标，不能只把同样承诺用更少数据完成。Plan B应保留科学问题最核心的检验能力。'),
('E06','论文摘要与结果的逐句对应','table', [['摘要句','对应材料','退回原因'],['研究目的','明确问题','目的与结果不一致'],['方法','实际设计和样本','省略关键对照限制'],['结果','图表和计算','添加正文没有的数字'],['结论','讨论与局限','推广超出采样范围']], '从教学段落制作摘要，不使用真实作者名包装教学结论。每句话标出对应的正文位置。摘要中的每个数字都与结果表逐项比较，限制不能为节省字数全部删除。'),
('E07','引文真实存在仍可能引用错误','compare', [['身份正确','题名、作者和DOI一致，解决“这篇文章是否存在”。'],['内容匹配','阅读原文，核对它是否支持当前句子，尤其留意相反结果。'],['适用条件','检查对象、设计、时间和限制，避免超出来源的主张。']], '用本课Gorman论文练习：形态数据不能独自支持海冰变化造成体重变化这一因果断言。文献核验工具输出URL不代表科学审查结束。对无法访问全文的条目标记访问范围。'),
('E08','申报创新点的可检验表达','compare', [['空泛表达','建立国际领先的智能科研平台，全面提升效率。'],['教学改写','对AI筛选的漏检类别建立可复核标注，比较加入人工复核前后的召回与耗时。'],['待确认','最接近研究是否已做同类比较？样本和参考答案能否取得？']], '创新性需要与最接近研究比较，不能由形容词决定。教学改写只是候选方案，尚未检索确认其新颖。要求每个创新点对应研究内容与验证，不用技术名词数量代替创新。'),
('E09','指南更新后的版本迁移','route', [['保存新旧指南','比较资格、字数与成果','标注条款位置'],['定位受影响章节','更新目标和指标映射','不机械全文重写'],['重新核验','检查模板与附件','旧批准不自动继承'],['版本归档','保存差异和审核记录','保留可追溯历史']], '这是工作流练习，不伪造任何真实基金政策变更。提供两个教学JSON版本，改变成果要求，要求脚本识别输入哈希变化。讨论哪些只是格式变化，哪些改变研究内容或资格。'),
('E10','专利附图与正文的一致性','table', [['检查项','问题实例','修正'],['标号','正文有3号控制器，图中只有1和2','统一部件表'],['连接','正文串联，图上并联','让发明人确认实际连接'],['步骤','判定前缺采样步骤','补充真实执行顺序'],['效果','图上增加未经确认的性能标签','删除并追问证据']], '所有问题实例为教学构造。图形编辑容易掩盖技术事实变化，因此每次修改保留发明人确认。结构完整不等于具备专利授权条件，正式审查需另行完成。'),
('E11','评审分歧需要可定位的回应','compare', [['审稿人A','要求更保守的因果表述。'],['审稿人B','要求提出机制解释。'],['作者处理','区分已支持的关联、候选机制和未来验证，逐项说明证据及文中位置。']], '模拟两条有张力的意见，不能简单选择容易执行的一条。作者可以同时给出谨慎结论和明确标注的机制假说。若没有新增实验，不写成已验证。回应保持礼貌和具体。'),
('E12','灰度和投影条件下的科研图','compare', [['冗余编码','颜色之外使用点型、线型或直接标签。'],['投影检查','在目标大小检查标签和坐标，不用高DPI弥补过小文字。'],['可编辑性','保留数据和绘图源码，图注单独可修改。']], '对本课散点图做灰度查看，检查三种物种是否仍能区分。投影检查需要实际设备确认，桌面渲染不能代替现场验收。避免用“符合无障碍标准”概括一次目视检查。'),
('E13','云端状态与失败恢复的演练','table', [['状态','允许动作','禁止误判'],['received','校验输入和权限','收到请求不等于已执行'],['running','保存中间输出','超时后不编造完成'],['review_required','研究者核对版本','模型不能代替人工批准'],['failed','保存错误和重试位置','不能显示成功下载'],['draft_ready','校验文件哈希','草稿不等于正式提交']], '用本地契约测试演练状态变更，不声称Cloudflare已部署。讨论幂等键、重复点击和输入修改。文件服务应在产物写完后才返回可下载状态，避免用户下载半成品。'),
('E14','把课程方法迁移到自己的学科','table', [['你的任务','需要填写','验收问题'],['输入','指南、论文、数据与权限','是否可合法处理'],['方法','步骤、工具和人工关口','哪些判断必须由专家做'],['产物','Word、图表、代码或证据表','是否可编辑和复算'],['限制','缺口、失败路径与外部条件','是否仍有未证实承诺']], '安排学员用一个实际项目填写迁移表，讲师选取一个匿名案例拆解。保留四模块结构：基本功、全过程、产出、结题。不同学科的伦理、数据结构和证据规范需要适配，不能照搬一个模板。')]
for i,title,kind,body,note in extensions:add(i,'延伸备课',title,kind,body,note,minutes=8,optional=True)
# Normalize timing to required module slots while retaining relative emphasis.
budgets={'开场':15,'模块一':65,'模块二':90,'模块三 A':40,'模块三 B':50,'模块三 C':35,'模块三 D':35,'模块四':25,'收尾':15,'延伸备课':110}
for mod,minutes in budgets.items():
    ss=[s for s in slides if s['module']==mod]; total=sum(s['estimated_time_sec'] for s in ss); used=0
    for s in ss[:-1]:s['estimated_time_sec']=round(s['estimated_time_sec']/total*minutes*60); used+=s['estimated_time_sec']
    ss[-1]['estimated_time_sec']=minutes*60-used
for s in slides:
    if s['id']=='M102':s['speaker_notes']+=' 原稿还列出Kimi等中文工具。产品更新很快，课堂按材料类型、实际试用和可验收产物选择，不保留永久的品牌能力排名。'
    if s['id']=='M201':s['speaker_notes']=s['speaker_notes'].replace('这是本课程的教学评估框架，不宣称为某基金官方评分表。','四维名称沿用客户原稿。讨论中另加可验证性检查，不把课堂评分当作基金官方标准。')
    if s['id']=='M203':s['speaker_notes']+=' 原稿还要求结合专利数据判断技术布局；先分别核对论文、预印本与专利的公开时间和证据性质，再做交叉解释。'
    if s['id']=='M104':s['body'][0][1]='输入材料，取得修改建议。研究者把修改写回文件，再检查格式和引用。'
    if s['id']=='M321':s['body'][0][0]='发明人说法\n（教学模拟）'
    if s['id']=='M206':
        s['body']=['Adélie 企鹅：横轴 δ¹³C，纵轴 δ¹⁵N。蓝色雄性、橙色雌性。','图注规定均值 ±1 SE。δ¹³C 的 n=127，δ¹⁵N 的 n=128。','年份和性别效应需结合正文模型解释。不能仅凭误差线重叠判定显著性。']
        s['speaker_notes']+=' 原文Figure3图注明确误差为1 SE，两个同位素分析样本量分别127和128。图中2008年的氮同位素均值较低，正式解释需结合Table4与正文模型。'
    if s['id']=='M210':s['body'][2]='比较需考虑物种、性别、岛屿和年份。\n当前散点图不证明因果作用。'
for n,s in enumerate(slides,1):s['page']=n;s['example_or_data']='teaching simulation' if s['source']=='teaching' else 'public source + teaching analysis';s['workflow_step']=s['id']
(R/'slides_manifest.json').write_text(json.dumps(slides,ensure_ascii=False,indent=2),'utf-8')
handbook='# 高校科研 AI 讲师手册\n\n正式授课370分钟，延伸110分钟。时长为编排预算，未做讲师实地全程彩排。\n\n'
for s in slides:handbook+=f'## {s["page"]:02d} {s["id"]} {s["title"]}\n\n{s["module"]}，{s["estimated_time_sec"]/60:.1f}分钟。来源：{s["source"]}。\n\n{s["speaker_notes"]}\n\n'
(R/'讲师手册.md').write_text(handbook,'utf-8')
print(len(slides),'slides;',sum(s.get('sample',False) for s in slides),'sample; main',sum(s['estimated_time_sec'] for s in slides if not s.get('optional'))/60,'min; extension',sum(s['estimated_time_sec'] for s in slides if s.get('optional'))/60,'min')
